def shortest_path(edges, start, end):
    """
    Find the shortest path from start to end in a directed graph.

    Args:
        edges: List of (from_node, to_node, weight) tuples
        start: Starting node
        end: Ending node

    Returns:
        Tuple of (distance, path) where distance is the total weight of the shortest
        path and path is the list of nodes from start to end.
        If start == end, returns (0, [start]).
        If no path exists, returns (None, None).
        Raises ValueError if any edge has negative weight.
    """
    # Check for negative weights
    for e in edges:
        if len(e) >= 3:
            if e[2] < 0:
                raise ValueError("Negative edge weight detected")

    # If start and end are the same
    if start == end:
        return (0, [start])

    # Build adjacency list
    graph = {}
    for e in edges:
        from_node, to_node, weight = e[0], e[1], e[2]
        if from_node not in graph:
            graph[from_node] = []
        graph[from_node].append((to_node, weight))

    # Dijkstra's algorithm
    import heapq

    # dist[node] = shortest distance from start to node
    dist = {start: 0}
    prev = {}  # To reconstruct path
    visited = set()
    heap = [(0, start)]

    while heap:
        d, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)

        if u == end:
            # Reconstruct path
            path = [end]
            while u != start:
                u = prev[u]
                path.append(u)
            path.reverse()
            return (d, path)

        for v, w in graph.get(u, []):
            if v not in dist or d + w < dist[v]:
                dist[v] = d + w
                prev[v] = u
                heapq.heappush(heap, (d + w, v))

    # No path exists
    return (None, None)
